def calculate_sumset_size(t):
    N = len(t)
    S = set()
    for i in range(N):
        for j in range(i, N):
            S.add(t[i] + t[j])
    return len(S)

# 1. Uniform sequence: t_i = floor(i * 171 / 86)
M = 171
N_indices = 87 # 0 to 86
t_uniform = [int(i * M / 86) for i in range(N_indices)]
size_uniform = calculate_sumset_size(t_uniform)

print(f"Uniform sequence size: {size_uniform}")

# 2. Highly structured sequence T': {0, 2, 4, ..., 170, 171}
t_structured = []
for i in range(86):
    t_structured.append(2 * i)
t_structured.append(171)
size_structured = calculate_sumset_size(t_structured)

print(f"Structured sequence size (T'): {size_structured}")

